name: web-dist
          path: ${{ env.ANGULAR_DIST_PATH }}/

  deploy-api:
    runs-on: windows-latest
    needs: [detect-changes, build-api]
    if: needs.detect-changes.outputs.api == 'true' || github.event_name == 'workflow_dispatch'

    steps:
      - name: Download API artifact
        uses: actions/download-artifact@v4
        with:
          name: api-publish
          path: ${{ env.PUBLISH_PATH }}/

      - name: Verify API artifact for Simply requirements
        shell: pwsh
        run: |
          $publishDir = "${{ env.PUBLISH_PATH }}"
          $exePath = Join-Path $publishDir "RecipeHub.Api.exe"
          $webConfigPath = Join-Path $publishDir "web.config"
          $productionSettingsPath = Join-Path $publishDir "appsettings.Production.json"
          $identityEfPath = Join-Path $publishDir "Microsoft.AspNetCore.Identity.EntityFrameworkCore.dll"

          if (-not (Test-Path $exePath)) {
            throw "Missing RecipeHub.Api.exe in publish output."
          }

          if (-not (Test-Path $webConfigPath)) {
            throw "Missing web.config in publish output."
          }

          if (-not (Test-Path $productionSettingsPath)) {
            throw "Missing appsettings.Production.json in publish output. The production database configuration was not included."
          }

          if (-not (Test-Path $identityEfPath)) {
            throw "Missing Microsoft.AspNetCore.Identity.EntityFrameworkCore.dll in publish output."
          }

          $webConfig = Get-Content $webConfigPath -Raw

          if ($webConfig -notmatch 'processPath="\.\\RecipeHub\.Api\.exe"') {
            throw "web.config processPath is not set to .\\RecipeHub.Api.exe"
          }

          if ($webConfig -notmatch 'hostingModel="outofprocess"|hostingModel="OutOfProcess"') {
            throw "web.config hostingModel is not OutOfProcess"
          }

          Write-Host "✅ Artifact check passed (SCD + win-x86 + OutOfProcess compatible layout)."

      - name: Prepare web.config and logs for startup diagnostics
        shell: pwsh
        run: |
          $webConfig = Join-Path "${{ env.PUBLISH_PATH }}" "web.config"
          if (Test-Path $webConfig) {
            (Get-Content $webConfig -Raw) -replace 'stdoutLogEnabled="false"', 'stdoutLogEnabled="true"' | Set-Content $webConfig -Encoding UTF8
          }

          $logsDir = Join-Path "${{ env.PUBLISH_PATH }}" "logs"
          if (-not (Test-Path $logsDir)) {
            New-Item -ItemType Directory -Path $logsDir | Out-Null
          }

          $placeholder = Join-Path $logsDir ".keep"
          if (-not (Test-Path $placeholder)) {
            Set-Content -Path $placeholder -Value "keep" -Encoding UTF8
          }

      - name: Deploy API using FTP
        id: deploy_api_primary
        continue-on-error: true
        uses: SamKirkland/FTP-Deploy-Action@v4.3.5
        with:
          server: ${{ secrets.FTP_SERVER }}
          username: ${{ secrets.FTP_USERNAME }}
          password: ${{ secrets.FTP_PASSWORD }}
          local-dir: ${{ env.PUBLISH_PATH }}/
          server-dir: /recipes.api/

- name: Health check Web
        shell: pwsh
        run: |
          if ([string]::IsNullOrWhiteSpace($env:WEB_HEALTH_URL)) {
            Write-Error "WEB_HEALTH_URL is not set"
          }
          Write-Host "Waiting 5 seconds for Web to start..."
          Start-Sleep -Seconds 5

          $retries = 5
          for ($i=1; $i -le $retries; $i++) {
            try {
              $resp = Invoke-WebRequest -UseBasicParsing -TimeoutSec 10 -Uri $env:WEB_HEALTH_URL
              if ($resp.StatusCode -ge 200 -and $resp.StatusCode -lt 500) {
                Write-Host "✅ Web healthy (status $($resp.StatusCode))"
                exit 0
              }
              throw "Unexpected status code $($resp.StatusCode)"
            } catch {
              Write-Host "Attempt $i failed: $_"
              if ($i -eq $retries) { throw }
              Start-Sleep -Seconds 5
            }
          }

