import { Component, OnDestroy, OnInit } from '@angular/core';
import { AbstractControl, UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { Subscription } from 'rxjs';
import { ForgotPasswordRequest } from '../shared/models/forgot-password.interface';
import { PasswordResetRequestResponse } from '../shared/responses/password-reset-request.interface';
import { UserService } from '../shared/services/user.service';

@Component({
    selector: 'app-forgot-password',
    templateUrl: './forgot-password.component.html',
    styleUrls: ['./forgot-password.component.css'],
    standalone: false
})

export class ForgotPasswordComponent implements OnInit, OnDestroy {

    private subscription: Subscription;
    public forgotForm: UntypedFormGroup;
    public isRequesting = false;
    public submitted = false;
    public errors = '';
    public message = '';
    public token: string | undefined;

    constructor(private formBuilder: UntypedFormBuilder, private userService: UserService) { }

    ngOnInit(): void {
        this.forgotForm = this.formBuilder.group({
            email: ['', [Validators.required, Validators.email]]
        });

        this.subscription = new Subscription();
    }

    ngOnDestroy(): void {
        if (this.subscription) {
            this.subscription.unsubscribe();
        }
    }

    submit({ value, valid }: { value: ForgotPasswordRequest; valid: boolean }) {
        this.submitted = true;
        this.isRequesting = true;
        this.errors = '';
        this.message = '';
        this.token = undefined;

        if (!valid) {
            this.isRequesting = false;
            return;
        }

        const resetRequest$ = this.userService.requestPasswordReset(value)
            .subscribe({
                next: (response: PasswordResetRequestResponse) => {
                    this.message = response.message ?? 'If an account exists for this email, a reset token has been generated.';
                    this.token = response.token;
                    this.isRequesting = false;
                },
                error: (error: any) => {
                    this.isRequesting = false;
                    this.errors = this.extractError(error);
                }
            });

        this.subscription.add(resetRequest$);
    }

    get f(): { [key: string]: AbstractControl } {
        return this.forgotForm.controls;
    }

    private extractError(error: any): string {
        const raw = error?.error ?? error;
        if (typeof raw === 'string') {
            return raw;
        }

        return 'Unable to process request.';
    }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { map } from 'rxjs/operators';
import { ConfigService } from '../shared/utils/config.service';
import { Fridge } from './models/fridge';
import { Observable } from 'rxjs';
import { FridgeGrocery } from './models/Fridge-grocery';

@Injectable({ providedIn: 'root'})
export class FridgeService {
    baseUrl: string = '';
    private httpOptions = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${localStorage.getItem('authToken')}`
      })
    };

    public recipeList: Fridge[] = [];
  
    constructor(private http: HttpClient, private configService: ConfigService) {
      this.baseUrl = configService.getApiURI();
    }
  
    get(userId: string): Observable<Fridge[]> {  
      return this.http.get<Fridge[]>(this.baseUrl + `/fridge/get?userId=${userId}`, this.httpOptions)
        .pipe(map(details => {
          return details;
        }, (error: any) => console.log(error, "fails")
      ));
    }
  
    add(fridge: Fridge) {  
      return this.http.post(this.baseUrl + "/fridge/add", fridge, this.httpOptions)
        .pipe(map(details => {
          return details;
        }, (error: any) => console.log(error, "fails")
      ));
    }
  
    retire(id: string) {  
      return this.http.post(this.baseUrl + `/fridge/retire?fridgeId=${id}`, null, this.httpOptions)
        .pipe(map(details => {
          return details;
        }, (error: any) => console.log(error, "fails")
      ));
    }
  
    unRetire(id: string) {  
      return this.http.post(this.baseUrl + `/fridge/unretire?fridgeId=${id}`, null, this.httpOptions)
        .pipe(map(details => {
          return details;
        }, (error: any) => console.log(error, "fails")
      ));
    }
  
    getGroceries(id: string): Observable<FridgeGrocery[]> {
        return this.http.get<FridgeGrocery[]>(this.baseUrl + `/fridge/getgroceries?fridgeId=${id}`, this.httpOptions)
        .pipe(map(details => {
            return details;
        }, (error: any) => console.log(error, "fails")
        ));
    }
  
    addGrocery(grocery: FridgeGrocery) {  
      return this.http.post(this.baseUrl + "/fridge/addgrocery", grocery, this.httpOptions)
        .pipe(map(details => {
          return details;
        }, (error: any) => console.log(error, "fails")
      ));
    }
  
    removeGrocery(id: string) {  
      return this.http.post(this.baseUrl + `/fridge/removegrocery?id=${id}`, null, this.httpOptions)
        .pipe(map(users => {
          return users;
        }, (error: any) => console.log(error, "fails")
      ));
    }
}

