            }

            await DeleteUsersAsync(users);

            _logger.LogTrace("Users have been deleted! Users: {@Users}", users);

            var cleanedUsers = await _userService.GetAll();

            return new OkObjectResult(cleanedUsers);
        }

        [HttpGet("getusers")]
