        {
            foreach (var user in users)
            {
                var result = await _userService.Delete(user);
                if (result.Succeeded == false)
                    _logger.LogError("Failed to delete user {UserId}. Errors: {@Errors}", user.Id, result.Errors);
            }
        }
    }
